<script setup>
import {computed,ref} from 'vue';
const props=defineProps({label:String,options:{type:Array,default:()=>[]},disabled:Boolean});const model=defineModel({type:Array,default:()=>[]});const open=ref(false),query=ref('');
const rows=computed(()=>props.options.map(x=>typeof x==='string'?{value:x,label:x}:x).filter(x=>String(x.label).toLowerCase().includes(query.value.toLowerCase())));
function toggle(value){model.value=model.value.includes(value)?model.value.filter(x=>x!==value):[...model.value,value];}
</script>
<template><div class="native-multiselect"><label>{{label}}</label><button type="button" :disabled="disabled" :aria-expanded="open" @click="open=!open">{{model.length?model.length+' selected':'All'}} ▾</button><div v-if="open" class="choices"><input v-model="query" type="search" :aria-label="'Search '+label" placeholder="Search…"><button type="button" @click="model=[]">Clear selection</button><button type="button" @click="model=rows.map(x=>x.value)">Select shown</button><label v-for="option in rows" :key="option.value"><input type="checkbox" :checked="model.includes(option.value)" @change="toggle(option.value)">{{option.label}} <small v-if="option.count!=null">({{option.count}})</small></label><button type="button" @click="open=false">Done</button></div></div></template>
<style scoped>.native-multiselect{position:relative;min-width:150px;display:grid;gap:5px}button,input{font:inherit}button{padding:8px;background:white;border:1px solid #c8decd;border-radius:6px;text-align:left}.choices{position:absolute;top:100%;left:0;min-width:240px;max-height:300px;overflow:auto;background:white;z-index:12;padding:10px;box-shadow:0 8px 28px #1233;border:1px solid #c8decd;display:grid;gap:7px}.choices label{display:flex;gap:7px;align-items:center}</style>
